 @Test public void popupSettingsEscapeCommentCategory(){Prefs a=Robolectric.buildActivity(Prefs.class).setup().get();PreferenceScreen root=a.getPreferenceManager().createPreferenceScreen(a);a.setPreferenceScreen(root);for(String k:new String[]{"player","comment","google_cast","setting_whole"}){PreferenceCategory g=new PreferenceCategory(a);g.setKey(k);root.addPreference(g);}PreferenceGroup comments=(PreferenceGroup)a.findPreference("comment");for(String k:new String[]{"popup_double_tap_seek","double_tap_seek_seconds","comment_cast_min"}){Preference p=new Preference(a);p.setKey(k);comments.addPreference(p);}SettingsPlacement233.finish(a);assertSame(a.findPreference("player"),SettingsTools.parent(root,a.findPreference("popup_double_tap_seek")));assertSame(a.findPreference("google_cast"),SettingsTools.parent(root,a.findPreference("comment_cast_min")));assertNotNull(a.findPreference(HorizontalSeek233.KEY));int count=((PreferenceGroup)a.findPreference("player")).getPreferenceCount();SettingsPlacement233.finish(a);assertEquals(count,((PreferenceGroup)a.findPreference("player")).getPreferenceCount());assertTrue(a.findPreference("double_tap_seek_seconds").getOrder()<a.findPreference("popup_double_tap_seek").getOrder());}
