 @Test public void tabLimitAndPersistenceRemainIndependent(){SavedTabs227 data=new SavedTabs227("{}");for(int i=0;i<64;i++){SavedTabs227.Tab t=new SavedTabs227.Tab();t.label="検索"+i;t.url="https://www.nicovideo.jp/search/video?keyword="+i;data.add(t);}String last=data.selected;SavedTabs227 restored=new SavedTabs227(data.save());assertEquals(64,restored.tabs.size());assertEquals(last,restored.selected);try{restored.add(new SavedTabs227.Tab());fail();}catch(IllegalStateException expected){}String first=restored.tabs.get(0).id;restored.remove(last);assertEquals(63,restored.tabs.size());assertNotNull(restored.find(first));}
 @Test public void playlistSnapshotInvalidatesOnActualChange()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();android.content.SharedPreferences p=PreferenceManager.getDefaultSharedPreferences(a);p.edit().putString("nicoid_local_playlists_v1","{}").commit();LocalPlaylistData first=LocalPlaylists.read(a);assertSame(first,LocalPlaylists.read(a));p.edit().putString("nicoid_local_playlists_v1","{\"folders\":[{\"id\":\"f\",\"name\":\"Test\"}]}").commit();LocalPlaylistData second=LocalPlaylists.read(a);assertNotSame(first,second);assertEquals(1,second.folders.length());}
