 @Test public void closedMiniSessionRejectsDelayedTransitions(){MiniState225 state=new MiniState225();assertTrue(state.drag(100,500));int token=state.settle(true);assertTrue(state.current(token));state.close();assertFalse(state.current(token));assertFalse(state.drag(300,500));assertEquals(-1,state.settle(true));state.cancel();assertFalse(state.live());}
